//! Conformance against the REAL official ECPayAIO_Python SDK: every vector
//! in `fixtures/python_sdk_vectors.json` was generated by executing the
//! upstream `sdk/ecpay_payment_sdk.py` (see `tests/fixtures/README.md`).
//!
//! Three deliberate divergences are pinned as such, not hidden:
//! * CheckMacValue escapes `~` to `%7e` (ECPay's .NET backend); the Python
//!   SDK hashes a literal `~`. See `tilde_divergence`.
//! * Invoice free-text fields are urlencoded but not lowercased (the SDK's
//!   `.lower()` corrupts ASCII letter case in customer data).
//! * Fields set outside their ChoosePayment group, and conflicting Credit
//!   plan groups, are validation errors (the SDK silently signs the mix).

use std::collections::{BTreeMap, HashMap};

use ecpay::payment::{
    union_pay, AioCheckOutParams, CarruerType, ChoosePayment, CreditAction, Donation, InvType,
    InvoiceExtend, PeriodType, PrintMark, TaxType,
};
use ecpay::Ecpay;

const FIXTURE: &str = include_str!("fixtures/python_sdk_vectors.json");

const TEST_MERCHANT_ID: &str = "3002607";
const TEST_HASH_KEY: &str = "pwFHCqoQZGmho4w6";
const TEST_HASH_IV: &str = "EkRm7iFT261dpevs";

fn sdk() -> Ecpay {
    Ecpay {
        merchant_id: TEST_MERCHANT_ID.to_owned(),
        hash_key: TEST_HASH_KEY.to_owned(),
        hash_iv: TEST_HASH_IV.to_owned(),
        ..Default::default()
    }
}

#[derive(serde::Deserialize)]
struct Fixture {
    create_order: HashMap<String, CreateOrderCase>,
    #[serde(default)]
    errors: HashMap<String, ErrCase>,
    check_value: HashMap<String, CheckValueCase>,
    html_form: HtmlFormCase,
    /// 156 seeded-random parameter maps signed by the real SDK (150
    /// tilde-free that must match byte-for-byte, 6 tilde-bearing that pin
    /// the %7e divergence).
    #[serde(default)]
    differential: HashMap<String, CheckValueCase>,
}

#[derive(serde::Deserialize)]
struct CreateOrderCase {
    #[serde(default)]
    ok: Option<Vec<Vec<String>>>,
}

#[derive(serde::Deserialize)]
struct ErrCase {
    error: Option<String>,
}

#[derive(serde::Deserialize)]
struct CheckValueCase {
    params: BTreeMap<String, String>,
    expected: String,
    #[serde(default)]
    dot_net_escaped: Option<String>,
}

#[derive(serde::Deserialize)]
struct HtmlFormCase {
    action: String,
    html: String,
}

fn fixture() -> Fixture {
    serde_json::from_str(FIXTURE).expect("parse python_sdk_vectors.json")
}

/// The scenario parameter sets, mirroring the generator's inputs (and the
/// official sample_*.py files) field for field. Empty-string optionals are
/// `None` — they drop out on the wire exactly like the SDK's filter stage.
